DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_1','Laureate Commonwealth[NEWLINE]Achievement-fed Golden Ages and cultured military finishing[NEWLINE]Culture; Diplomacy or supported Domination[NEWLINE][NEWLINE]Develop several genuine achievement sources, contribute Hall income, and let the normal Golden Age system do its work. Use the resulting Great Person and combat-experience window to create the next meaningful achievements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_2','Build a stable economy, feasible Wonders and useful cultural infrastructure. Preserve developing military units instead of forcing a Level 3 reward through a bad fight. Ordinary defenses and strategic resources still matter.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_3','Use Halls and specialist cities to support a recurring Golden Age plan. Laureate recognizes a broader range of newly created Great People than the Paradise Dreams system; captured or administrative replacements are not equivalent new achievements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_4','Convert Golden Age support into real Tourism, diplomacy or trained armies. Let ranged damage create useful Crowning Blow targets, preserve upgraded Champions, and keep functioning Halls out of avoidable resistance or loss.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_5','- World Wonders, new Great People and developing military veterans contribute to one native meter.[NEWLINE]- Golden Ages support specialist Great Person generation and military combat XP.[NEWLINE]- Champions can finish wounded military targets and heal after qualifying kills.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_6','- Points do not create an immediate custom Golden Age or change its native threshold.[NEWLINE]- Veteran recognition is once per lifetime and does not reward imported high-level history.[NEWLINE]- The Champion''s attack bonus is not a defensive, healthy-target or city-attack bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_7','- Avoid feeding wounded military units to a preserved Champion.[NEWLINE]- Contest realistic Wonders and threaten the cities supporting specialists and functioning Halls.[NEWLINE]- Apply pressure between Golden Ages rather than assuming the experience modifier lasts permanently.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_8','- Counting captured or National Wonders as the World Wonder achievement.[NEWLINE]- Expecting repeated Level 3 recognition from the same veteran.[NEWLINE]- Treating Golden Age Points as Tourism or an automatic immediate Golden Age start.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Wounded Project attackers can become valuable Champion finishes before they complete a SEND.[NEWLINE][NEWLINE]Substitute Classroom: A prepared Golden Age programme can sustain development and XP while the classroom''s selected bonuses are inactive.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated attacking window can remove developing veterans before they reach or exploit their milestones.[NEWLINE][NEWLINE]The Filthy Realm: Economic and cultural-city disruption can make the specialist and Hall base harder to keep productive.');
