INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_BACKGROUND','Develop several genuine achievement sources, contribute Hall income, and let the normal Golden Age system do its work. Use the resulting Great Person and combat-experience window to create the next meaningful achievements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LAUREATE_CIV_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_BACKGROUND','Develop several genuine achievement sources, contribute Hall income, and let the normal Golden Age system do its work. Use the resulting Great Person and combat-experience window to create the next meaningful achievements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LAUREATE_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_STRATEGY','Develop several genuine achievement sources, contribute Hall income, and let the normal Golden Age system do its work. Use the resulting Great Person and combat-experience window to create the next meaningful achievements.[NEWLINE][NEWLINE]Build a stable economy, feasible Wonders and useful cultural infrastructure. Preserve developing military units instead of forcing a Level 3 reward through a bad fight. Ordinary defenses and strategic resources still matter.[NEWLINE][NEWLINE]Use Halls and specialist cities to support a recurring Golden Age plan. Laureate recognizes a broader range of newly created Great People than the Paradise Dreams system; captured or administrative replacements are not equivalent new achievements.[NEWLINE][NEWLINE]Convert Golden Age support into real Tourism, diplomacy or trained armies. Let ranged damage create useful Crowning Blow targets, preserve upgraded Champions, and keep functioning Halls out of avoidable resistance or loss.');
