INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_TEXT_2','Build a stable economy, feasible Wonders and useful cultural infrastructure. Preserve developing military units instead of forcing a Level 3 reward through a bad fight. Ordinary defenses and strategic resources still matter.[NEWLINE][NEWLINE]Use Halls and specialist cities to support a recurring Golden Age plan. Laureate recognizes a broader range of newly created Great People than the Paradise Dreams system; captured or administrative replacements are not equivalent new achievements.[NEWLINE][NEWLINE]Convert Golden Age support into real Tourism, diplomacy or trained armies. Let ranged damage create useful Crowning Blow targets, preserve upgraded Champions, and keep functioning Halls out of avoidable resistance or loss.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THELAUREATECOMMONWEALTH_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Wounded Project attackers can become valuable Champion finishes before they complete a SEND.[NEWLINE][NEWLINE]Substitute Classroom: A prepared Golden Age programme can sustain development and XP while the classroom''s selected bonuses are inactive.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated attacking window can remove developing veterans before they reach or exploit their milestones.[NEWLINE][NEWLINE]The Filthy Realm: Economic and cultural-city disruption can make the specialist and Hall base harder to keep productive.');
